() => {
                            const val =
                                inputEl.value.trim() || "/api/v1/fallback";
                            const cleanPath = val.replace("/api/v1/", "");

                            btnRun.innerHTML =
                                '<span class="material-symbols-outlined text-[16px] animate-spin">refresh</span><span>Processando...</span>';

                            setTimeout(() => {
                                const latency = (
                                    Math.random() * 2 +
                                    1.2
                                ).toFixed(2);
                                resTime.textContent = latency + "ms";

                                if (cleanPath.startsWith("internal/")) {
                                    resBadge.textContent = "403 Forbidden";
                                    resBadge.className =
                                        "px-2 py-0.5 rounded bg-error-container/20 text-error font-label-badge text-label-badge font-semibold";
                                    jsonOutput.innerHTML = `{\n  <span class="text-error">"detail"</span>: <span class="text-secondary">"Acesso restrito ao subsistema confidencial."</span>\n}`;
                                } else {
                                    resBadge.textContent = "200 OK";
                                    resBadge.className =
                                        "px-2 py-0.5 rounded bg-secondary-container/20 text-secondary font-label-badge text-label-badge font-semibold";
                                    jsonOutput.innerHTML = `{\n  <span class="text-primary">"status"</span>: <span class="text-secondary">"routed"</span>,\n  <span class="text-primary">"resolved_path"</span>: <span class="text-secondary">"${cleanPath}"</span>,\n  <span class="text-primary">"cache_hit"</span>: <span class="text-tertiary">true</span>,\n  <span class="text-primary">"middleware_telemetry"</span>: {\n    <span class="text-primary">"request_id"</span>: <span class="text-secondary">"req_${Math.random().toString(36).substring(2, 10)}-aura"</span>,\n    <span class="text-primary">"latency_ms"</span>: ${latency}\n  }\n}`;
                                }
                                btnRun.innerHTML =
                                    '<span class="material-symbols-outlined text-[16px]">play_arrow</span><span>Testar Endpoint</span>';
                            }, 350);
                        }

